class RoundTwoRepros(unittest.TestCase):
    @unittest.skipIf(os.environ.get("JOULEWISE_REVIEW_DISCOVERY_CHILD"),
                     "outer CI module runs repros once; historical nested discovery does not repeat them")
    def test_repros(self):
        root = Path(__file__).resolve().parents[2]
        with tempfile.TemporaryDirectory(prefix="r2-") as directory:
            base = Path(directory)
            scripts = base / "scripts"
            scripts.mkdir()
            for name, source in SOURCES.items():
                target = base / name if name.startswith("shade-") else scripts / name
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(source, encoding="utf-8")
            commands = [
                ("r2_integration.py", str(base / "shade-6da/endpoints.py")),
                ("r2_integration.py", str(base / "shade-5bb/endpoints.py")),
                ("r2_episodes.py",),
                ("r2_edges.py",),
                ("r2_matrix.py", str(root)),
            ]
            for name, *args in commands:
                command = [sys.executable, "-I", str(scripts / "run_in.py"),
                           str(root), str(scripts / name), *args]
                started = time.monotonic()
                result = subprocess.run(command, cwd=root, text=True, capture_output=True)
                print("R2_REPRO " + PHASE + " " + repr(command) + "\n" +
                      result.stdout + result.stderr +
                      "\nR2_WALL_SECONDS " + repr(time.monotonic() - started),
                      file=sys.stderr, flush=True)
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertNotIn("\nFAIL ", result.stdout)

            # Explicit module loads validate the current code without recursive
            # discovery; this temporary harness is removed after CI evidence.
            modules = sorted("tests.align." + p.stem for p in (root / "tests/align").glob("test*.py")
                             if p.name != Path(__file__).name)
            for names in (["tests.align.test_runner_review"], modules):
                command = [sys.executable, "-m", "unittest", *names]
                started = time.monotonic()
                result = subprocess.run(command, cwd=root, text=True, capture_output=True)
                print("R2_VALIDATION " + repr(command) + "\n" + result.stdout + result.stderr +
                      "\nR2_WALL_SECONDS " + repr(time.monotonic() - started),
                      file=sys.stderr, flush=True)
                self.assertEqual(result.returncode, 0, result.stderr)

if __name__ == "__main__":
    unittest.main()
